import subprocess
import os
import glob
import time
def task_func(test_dir):
    results = {}
    for script in glob.glob(os.path.join(test_dir, '*.py')):
        start_time = time.time()
        try:
            subprocess.run(['python', script], capture_output=True, timeout=30)
        except subprocess.TimeoutExpired:
            pass
        except Exception:
            pass
        elapsed_time = time.time() - start_time
        results[os.path.basename(script)] = elapsed_time
    return results

