import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    try:
        data = []
        start_time = time.time()
        end_time = start_time + duration
        if platform.system() == "Windows":
            cmd = ["wmic", "cpu", "get", "loadpercentage"]
        else:
            cmd = ["mpstat", "1", "1"]
        while time.time() < end_time:
            current_time = time.time()
            try:
                if platform.system() == "Windows":
                    output = subprocess.check_output(cmd, shell=True).decode()
                    lines = output.strip().split('\n')
                    for line in lines:
                        if line.strip().isdigit():
                            cpu_usage = float(line.strip())
                            break
                    else:
                        cpu_usage = 0.0
                else:
                    output = subprocess.check_output(cmd, shell=True).decode()
                    lines = output.strip().split('\n')
                    for line in lines:
                        if 'all' in line:
                            parts = line.split()
                            cpu_usage = 100.0 - float(parts[-1])
                            break
                    else:
                        cpu_usage = 0.0
            except:
                cpu_usage = 0.0
            data.append({"timestamp": current_time, "cpu_usage": cpu_usage})
            time.sleep(interval)
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

