import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    process_running = False
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            process_running = True
            break
    if not process_running:
        subprocess.Popen([process_name], shell=True)
        return f"Process not found. Starting {process_name}."
    else:
        for proc in psutil.process_iter(['name', 'pid']):
            if proc.info['name'] == process_name:
                proc.terminate()
                proc.wait()
        time.sleep(1)
        subprocess.Popen([process_name], shell=True)
        return f"Process found. Restarting {process_name}."

import subprocess
import platform
import time
def task_func(url):
    if platform.system() == 'Windows':
        process = subprocess.Popen(['start', url], shell=True)
    elif platform.system() == 'Darwin':
        process = subprocess.Popen(['open', url])
    else:
        process = subprocess.Popen(['xdg-open', url])
    time.sleep(1)
    process.poll()
    return process.returncode

