import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': f'Source folder {src_folder} does not exist', 'failed_files': []}
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception as e:
            return {'success': False, 'message': f'Failed to create destination folder: {e}', 'failed_files': []}
    files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    failed_files = []
    success = True
    for filename in files:
        src_path = os.path.join(src_folder, filename)
        gz_filename = filename + '.gz'
        dst_path = os.path.join(dst_folder, gz_filename)
        try:
            result = subprocess.run(['gzip', '-c', src_path], capture_output=True, check=True)
            with open(dst_path, 'wb') as f:
                f.write(result.stdout)
        except Exception as e:
            failed_files.append(filename)
            success = False
    if success:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}
    else:
        return {'success': False, 'message': f'Failed to process {len(failed_files)} file(s)', 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        p = psutil.Process(proc.pid)
        cpu_usage = 0.0
        mem_usage = 0
        start_time = time.time()
        while proc.poll() is None:
            if time.time() - start_time > timeout:
                proc.terminate()
                proc.wait()
                break
            try:
                cpu_percent = p.cpu_percent(interval=0.1)
                mem_info = p.memory_info()
                cpu_usage += cpu_percent * 0.1
                mem_usage += mem_info.rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            time.sleep(0.1)
        return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
